# ---------------------------------------------------------------- canvas
class Canvas:
    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.buf = bytearray(w * h * 3)
        r, g, b = bg
        for i in range(0, len(self.buf), 3):
            self.buf[i] = r
            self.buf[i + 1] = g
            self.buf[i + 2] = b
        self.clip = (0, 0, w, h)

    def set_clip(self, rect):
        self.clip = rect if rect is not None else (0, 0, self.w, self.h)

    def fill_rect(self, x, y, w, h, color):
        x0 = int(round(x))
        y0 = int(round(y))
        x1 = int(round(x + w))
        y1 = int(round(y + h))
        cx0, cy0, cw, chh = self.clip
        x0 = max(x0, cx0)
        y0 = max(y0, cy0)
        x1 = min(x1, cx0 + cw)
        y1 = min(y1, cy0 + chh)
        if x1 <= x0 or y1 <= y0:
            return
        r, g, b = color
        stride = self.w * 3
        row = bytes((r, g, b)) * (x1 - x0)
        for yy in range(y0, y1):
            off = yy * stride + x0 * 3
            self.buf[off:off + len(row)] = row

    def blit_alpha(self, alpha, bw, bh, x, y, color):
        """Blit a greyscale alpha bitmap in `color` onto the canvas."""
        cx0, cy0, cw, chh = self.clip
        r, g, b = color
        for row in range(bh):
            yy = y + row
            if yy < cy0 or yy >= cy0 + chh or yy < 0 or yy >= self.h:
                continue
            base = row * bw
            off = (yy * self.w + x) * 3
            for col in range(bw):
                xx = x + col
                if xx < cx0 or xx >= cx0 + cw or xx < 0 or xx >= self.w:
                    continue
                a = alpha[base + col]
                if a == 0:
                    continue
                o = off + col * 3
                if a == 255:
                    self.buf[o] = r
                    self.buf[o + 1] = g
                    self.buf[o + 2] = b
                else:
                    self.buf[o] = (r * a + self.buf[o] * (255 - a)) // 255
                    self.buf[o + 1] = (g * a + self.buf[o + 1] * (255 - a)) // 255
                    self.buf[o + 2] = (b * a + self.buf[o + 2] * (255 - a)) // 255

    def fill_polygon(self, pts, color):
        """Even-odd scanline polygon fill, clipped to the clip rect."""
        if len(pts) < 3:
            return
        cx0, cy0, cw, chh = self.clip
        min_y = max(cy0, int(min(p[1] for p in pts)))
        max_y = min(cy0 + chh - 1, int(max(p[1] for p in pts)))
        r, g, b = color
        stride = self.w * 3
        edges = []
        n = len(pts)
        for i in range(n):
            x0, y0 = pts[i]
            x1, y1 = pts[(i + 1) % n]
            if y0 != y1:
                edges.append((y0, y1, x0, x1))
        for yy in range(min_y, max_y + 1):
            yc = yy + 0.5
            spans = []
            for (y0, y1, x0, x1) in edges:
                if (y0 <= yc < y1) or (y1 <= yc < y0):
                    t = (yc - y0) / (y1 - y0)
                    spans.append(x0 + t * (x1 - x0))
            if not spans:
                continue
            spans.sort()
            for k in range(0, len(spans) - 1, 2):
                xa = max(cx0, int(spans[k]))
                xb = min(cx0 + cw, int(spans[k + 1]))
                if xb > xa:
                    off = yy * stride + xa * 3
                    self.buf[off:off + (xb - xa) * 3] = bytes((r, g, b)) * (xb - xa)

    def fill_circle(self, cx, cy, rad, color):
        r = int(round(rad))
        cx = int(round(cx))
        cy = int(round(cy))
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            dx = int((r * r - dy * dy) ** 0.5)
            self.fill_rect(cx - dx, yy, dx * 2 + 1, 1, color)

    def ring(self, cx, cy, rad, thick, color):
        self.fill_circle(cx, cy, rad, color)
        self.fill_circle(cx, cy, rad - thick, PAPER)

    def thick_line(self, x0, y0, x1, y1, width, color):
        dx, dy = x1 - x0, y1 - y0
        ln = (dx * dx + dy * dy) ** 0.5
        if ln == 0:
            return
        nx, ny = -dy / ln * width / 2.0, dx / ln * width / 2.0
        self.fill_polygon([(x0 + nx, y0 + ny), (x1 + nx, y1 + ny),
                           (x1 - nx, y1 - ny), (x0 - nx, y0 - ny)], color)

    def round_rect(self, x, y, w, h, rad, color):
        self.fill_rect(x + rad, y, w - 2 * rad, h, color)
        self.fill_rect(x, y + rad, w, h - 2 * rad, color)
        for (cx, cy) in ((x + rad, y + rad), (x + w - rad, y + rad),
                         (x + rad, y + h - rad), (x + w - rad, y + h - rad)):
            self.fill_circle(cx, cy, rad, color)

    def rect_outline(self, x, y, w, h, thick, color):
        self.fill_rect(x, y, w, thick, color)
        self.fill_rect(x, y + h - thick, w, thick, color)
        self.fill_rect(x, y, thick, h, color)
        self.fill_rect(x + w - thick, y, thick, h, color)


# ---------------------------------------------------------------- PNG writer
def _chunk(kind, data):
    out = struct.pack(">I", len(data)) + kind + data
    out += struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)
    return out


def write_png(path, cv):
    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)  # filter: None
        raw.extend(cv.buf[y * stride:(y + 1) * stride])
    comp = zlib.compress(bytes(raw), 6)
    png = b"\x89PNG\r\n\x1a\n"
    png += _chunk(b"IHDR", struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0))
    png += _chunk(b"IDAT", comp)
    png += _chunk(b"IEND", b"")
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "wb") as f:
        f.write(png)
    return len(png)

