# ---------------------------------------------------------------- text utils
def wrap_text(font, size, text, max_w):
    words = text.split(" ")
    lines = []
    cur = ""
    for wd in words:
        trial = (cur + " " + wd).strip()
        if font.width(trial, size) <= max_w or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = wd
    if cur:
        lines.append(cur)
    return lines


def draw_kicker(cv, x, y, w, h, label, badge):
    """Kicker bar with a DEDICATED badge slot on the right.

    The badge never touches the text: the label is measured and asserted
    to end at least 8px before the badge slot begins.
    """
    cv.fill_rect(x, y, w, h, NAVY)
    tsize = 11.0 if h >= 20 else 9.5
    bsize = 9.5 if h >= 20 else 8.5
    bw = SANSB.width(badge, bsize) + 12
    bh = h - 6
    bx = x + w - 6 - bw
    by = y + 3
    tw = SANSB.width(label, tsize)
    assert tw <= bx - 8 - (x + 8), \
        "kicker overflows badge slot: %r %.1f > %.1f" % (label, tw,
                                                        bx - 8 - (x + 8))
    SANSB.draw(cv, label, tsize, x + 8, y + h / 2 + tsize * 0.36, WHITE)
    cv.round_rect(bx, by, bw, bh, 3, BADGE_FILL[badge])
    SANSB.draw(cv, badge, bsize, bx + bw / 2, by + bh / 2 + bsize * 0.36,
               WHITE, align="center")


def draw_big(cv, text, size, cx, y_baseline, color):
    """Big art word/number with a soft dark shadow for contrast."""
    SANSB.draw(cv, text, size, cx + 1.5, y_baseline + 1.5, (0, 0, 0),
               align="center")
    SANSB.draw(cv, text, size, cx, y_baseline, color, align="center")


# ---------------------------------------------------------------- art panels
# Every painter receives (cv, x, y, w, h, big) and MUST stay inside its
# rect; render() also sets a hard clip rect before calling it, so a
# painter bug can never spill art onto a header or headline.
def art_chart(cv, x, y, w, h, big):
    cv.fill_rect(x, y, w, h, (18, 52, 38))
    for gy in range(1, 4):
        yy = y + h * gy / 4
        cv.fill_rect(x + 8, yy, w - 16, 1, (38, 90, 66))
    pts = [(x + 10, y + h - 22), (x + w * 0.25, y + h - 40),
           (x + w * 0.45, y + h - 34), (x + w * 0.62, y + h - 58),
           (x + w * 0.8, y + h - 66), (x + w - 12, y + 16)]
    for i in range(len(pts) - 1):
        cv.thick_line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1],
                      3, GOLD)
    cv.fill_circle(pts[-1][0], pts[-1][1], 4, GOLD)
    draw_big(cv, big, 30, x + w / 2, y + h - 8, WHITE)


def art_skyline(cv, x, y, w, h, big):
    cv.fill_rect(x, y, w, h, (31, 41, 55))
    cv.fill_circle(x + w * 0.8, y + 16, 7, (253, 230, 138))
    for i, (bw, bh) in enumerate([(34, 52), (26, 68), (40, 44), (28, 60)]):
        bx = x + 10 + i * (w - 20) / 4
        cv.fill_rect(bx, y + h - bh, bw, bh, (17, 24, 39))
        for wy in range(3):
            for wx in range(2):
                if (i + wx + wy) % 2 == 0:
                    cv.fill_rect(bx + 5 + wx * 12, y + h - bh + 6 + wy * 14,
                                 5, 6, (253, 211, 92))
    draw_big(cv, big, 34, x + w / 2, y + 34, WHITE)


def art_globe(cv, x, y, w, h, big):
    cv.fill_rect(x, y, w, h, (13, 84, 68))
    cx, cy, r = x + w / 2, y + h / 2 - 10, 26
    cv.fill_circle(cx, cy, r, (226, 240, 232))
    cv.ring(cx, cy, r, 2, (13, 84, 68))
    cv.thick_line(cx - r, cy, cx + r, cy, 1, (13, 84, 68))
    cv.fill_rect(cx - 1, cy - r, 2, 2 * r, (13, 84, 68))
    for k in (-0.5, 0.5):
        cv.thick_line(cx - r * 0.86, cy + k * r, cx + r * 0.86, cy + k * r,
                      1, (13, 84, 68))
    draw_big(cv, big, 20, x + w / 2, y + h - 8, WHITE)


